VRT_L("tle-c-svt-r41",{"duree":20,"titre":"Les biocarburants","accroche":"Une énergie à partir de la biomasse.","intro":"Les biocarburants proviennent de matières organiques renouvelables.","objectifs":["définir les biocarburants","décrire la production","discuter les limites"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>Un <strong>biocarburant</strong> est un carburant issu de la biomasse. Le bioéthanol vient de la fermentation de sucres ; le biodiesel vient d'huiles végétales.</div>"},{"t":"La production","verrou":true},{"t":"Limites","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle C","m":"svt","rang":41,"apc":{"module":"Catastrophes et valorisation","famille":"Préservation de l'environnement","agir":"Prévenir les catastrophes et valoriser les ressources de son environnement","situation":"Une unité agricole de Mbalmayo veut valoriser des résidus de canne à sucre.","tache":"Propose un produit et son principe."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-c-svt-r42",{"duree":20,"titre":"Intégration : une énergie pour le village","accroche":"Déchets agricoles ou forêt ?","intro":"Cette séance mobilise les notions du chapitre pour résoudre une situation réelle, comme à la partie B de l'épreuve.","objectifs":["identifier le problème","mobiliser les ressources","rédiger une réponse argumentée"],"parties":[{"t":"La notion à mobiliser","html":"<div class='def'><b>Définition</b>Une <strong>énergie renouvelable</strong> doit préserver les ressources et les cultures alimentaires.</div>"},{"t":"Le plan de la réponse","verrou":true},{"t":"La production attendue","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle C","m":"svt","rang":42,"apc":{"module":"Catastrophes et valorisation","famille":"Préservation de l'environnement","agir":"Prévenir les catastrophes et valoriser les ressources de son environnement","situation":"Une communauté de l'Est veut réduire le bois de chauffe pour protéger la forêt.","tache":"Propose une solution énergétique."},"verrou":true,"nq":10,"labo":true});
